from lib import *
S = SS('p16')
steps = [
    step("服务器每个请求停 0.1 秒,看不同并发量下线程池(requests)和 asyncio(aiohttp)完成 1000 个请求(并发 1 和 10 分别是 40、200 个)的总耗时,和理论下限(请求数 / 并发 × 0.1 秒)对比:并发 1:4258 / 4172 ms(下限 4000);并发 10:2168 / 2149(下限 2000);并发 50:2179 / 2164(下限 2000);并发 100:1171 / 1125(下限 1000);并发 200:698 / 615(下限 500)。I/O 等待占主导时,两种方式都紧贴下限,到 200 才拉开一点差距(83 ms)。并发 300 时线程池版被测试服务器重置了连接(失败),asyncio 版是 530 ms——这是我的测试服务器和 macOS 监听队列上限(128)的问题,不能当结论。", t=tl(S(1)), done=lidx(S(1), '     50', '    100', '    200'), mark=lidx(S(1), '失败:ConnectionError', '说明'), b=bars([['并发 200:线程池 ms', 698, '698'], ['并发 200:asyncio ms', 615, '615'], ['理论下限 ms', 500, '500']], 700, mark=[0], done=[1]), kv=KV([['并发 10–100', '线程池与 asyncio 几乎一样'], ['并发 200', '698 ms 对 615 ms,下限 500'], ['并发 300', '线程池版被服务器重置(不可靠)']], ['并发 200'])),
    step("服务器不延迟、3000 个请求、并发 50,看纯客户端开销:线程池 requests 每个请求平均 0.331 ms(总 993 ms),asyncio aiohttp 平均 0.109 ms(总 328 ms),约 3 倍。注意这个对比里换掉的不只是并发模型,还有 HTTP 客户端库(requests 与 aiohttp),两者的差别没有单独拆开。", t=tl(S(2)), done=lidx(S(2), 'asyncio aiohttp'), mark=lidx(S(2), '线程池 requests'), b=bars([['线程池 requests 每请求 ms', 0.331, '0.331'], ['asyncio aiohttp 每请求 ms', 0.109, '0.109']], 0.35, mark=[0], done=[1]), kv=KV([['线程池 requests', '0.331 ms / 请求'], ['asyncio aiohttp', '0.109 ms / 请求'], ['注意', '同时换了库和并发模型']], ['注意'])),
    step("内存(各在独立子进程里测峰值内存,起点是导入库之后约 46.5 MiB):并发 10:线程池 49.4 MiB、asyncio 47.1 MiB;并发 100:56.5 / 48.5;并发 200:65.3 / 49.7。线程池比起点多出 3.0 → 10.0 → 18.8 MiB,随并发线性增长(每个线程大约 0.09 MiB);asyncio 只多出 0.5 → 1.9 → 3.3 MiB。", t=tl(S(3)), done=lidx(S(3), '     200'), mark=lidx(S(3), '     100'), b=bars([['并发 200:线程池多出 MiB', 18.8, '18.8'], ['并发 200:asyncio 多出 MiB', 3.3, '3.3']], 20, mark=[0], done=[1]), kv=KV([['线程池', '每个并发约多 0.09 MiB'], ['asyncio', '并发 200 只多 3.3 MiB'], ['起点', '导入库后约 46.5 MiB']], ['线程池'])),
]
A = mkartp('p16', 16, '爬虫,并发,线程池,asyncio,aiohttp,requests,吞吐,内存,Python,真实验证,动画演示',
    '在本机测试服务器(每个请求停 0.1 秒)上对比线程池 requests 与 asyncio aiohttp:并发 10 到 100 时都紧贴理论下限,并发 200 时 698 ms 对 615 ms;无延迟时每请求 0.331 ms 对 0.109 ms;并发 200 的峰值内存比起点多 18.8 MiB 对 3.3 MiB。',
    '“爬虫该用线程还是 asyncio”几乎是必争的话题。这篇不讲道理,在本机用 0.1 秒延迟的服务器测:并发量逐步加大,总耗时离理论下限有多远、纯客户端开销差多少、内存怎么涨。',
    [('615 对 698 ms', '并发 200、1000 个请求,asyncio aiohttp 与线程池 requests 的总耗时(下限 500)'), ('0.109 对 0.331 ms', '服务器不延迟时,每个请求的客户端开销(aiohttp 对 requests)'), ('3.3 对 18.8 MiB', '并发 200 时 asyncio 与线程池比起点多占的内存')],
    [('等待占主导时,两者一样', '<p>服务器每个请求停 0.1 秒,并发 10 到 100 时,线程池和 asyncio 的总耗时都只比理论下限多一点点,互相之间差不到 5%。I/O 等待是主要成本时,并发模型不是瓶颈。并发 200 时才看出 83 ms 的差距;并发 300 时线程池一侧遇到了我的测试服务器的连接重置(macOS 监听队列上限 128),不能说明线程池撑不住 300。</p>'),
     ('每个请求的客户端开销', '<p>服务器不延迟时,请求本身没有等待,剩下的是客户端 CPU 开销:线程池 requests 每个请求 0.331 ms,asyncio aiohttp 0.109 ms。这里换掉的是整套库,不只是线程对协程;要单独比较并发模型,需要在同一个库(比如 <code>curl_cffi</code> 的同步和异步版本)上做,我没有做。</p>'),
     ('内存', '<p>线程池里每多一个并发就多一个线程,峰值内存随并发线性增长:并发 200 时多出 18.8 MiB(约每线程 0.09 MiB)。asyncio 同样的并发只多出 3.3 MiB。这里的内存是 <code>ru_maxrss</code>(峰值常驻内存),且请求体很小;爬真实页面时解析结果占的内存会盖过这一项。</p>')],
    steps,
    [ENV_P + '。服务器每个请求 time.sleep(0.1) 后返回 200 字节;线程池是 ThreadPoolExecutor(并发数)配合同一个 requests.Session(连接池大小等于并发数);asyncio 是 aiohttp(TCPConnector(limit=0))加 Semaphore(并发数);每个并发量各测 2 次取中位数,无延迟的开销测 3 次取中位数;内存在独立的子进程里用 resource.getrusage 测峰值',
     '没有验证:并发超过 200 的情形(测试服务器的监听队列限制了它);真实网络下的长连接和更大的响应体;CPU 密集的解析混在其中时的表现(后面有单独的文章);同一个库的同步版与异步版的对比(如 curl_cffi);Python 自由线程(no-GIL)构建下的线程池;uvloop 等替代事件循环'],
    '线程池与 asyncio')
